-- V17.5：依据《数字化编码与审批标准库0622 - 副本》切换当前数字化结构，并导入审批/智选所需案例数据。
-- 历史16位数据不删除，仅保留兼容读取。当前新结构：模型19位、员工11位、业务属性19位、数字化标识19位、组织/组织名称属性12位。

-- 1. 放宽历史16位约束，启用当前对象分型编码。
ALTER TABLE users DROP CONSTRAINT IF EXISTS users_employee_code_16_check;
ALTER TABLE users DROP CONSTRAINT IF EXISTS users_employee_code_current_or_legacy_check;
ALTER TABLE users ADD CONSTRAINT users_employee_code_current_or_legacy_check
  CHECK (employee_code ~ '^5011002[0-9]{4}$' OR employee_code ~ '^[0-9]{16}$');

ALTER TABLE digital_codes DROP CONSTRAINT IF EXISTS digital_codes_code_check;
ALTER TABLE digital_codes DROP CONSTRAINT IF EXISTS digital_codes_current_or_legacy_check;
ALTER TABLE digital_codes ADD CONSTRAINT digital_codes_current_or_legacy_check CHECK (
  (object_type='model' AND (code ~ '^[0-9]{19}$' OR code ~ '^[0-9]{16}$')) OR
  (object_type='person' AND (code ~ '^5011002[0-9]{4}$' OR code ~ '^[0-9]{16}$')) OR
  (object_type='organization' AND (code ~ '^[0-9]{12}$' OR code ~ '^[0-9]{16}$')) OR
  (object_type='other' AND code ~ '^[0-9]{11,19}$')
);

ALTER TABLE digital_identifiers DROP CONSTRAINT IF EXISTS digital_identifiers_code_check;
ALTER TABLE digital_identifiers DROP CONSTRAINT IF EXISTS digital_identifiers_current_or_legacy_check;
ALTER TABLE digital_identifiers ADD CONSTRAINT digital_identifiers_current_or_legacy_check
  CHECK (code ~ '^5013[0-9]{15}$' OR code ~ '^[0-9]{16}$');

SELECT setval('employee_digital_code_seq',GREATEST(COALESCE((SELECT max(right(employee_code,4)::bigint) FROM users WHERE employee_code ~ '^5011002[0-9]{4}$'),0),14),true);

-- 2. 当前显示名称统一为“数字化库”，不恢复标准库/非标准库概念。
UPDATE models SET name='员工信息模型',category='数字化基础',description='维护员工数字化编码、组织数字化属性、组织名称数字化属性、业务领域和身份' WHERE id='model-std-person';
UPDATE models SET name='组织名称数字化模型',category='数字化基础',description='维护组织名称数字化属性、组织名称和组织性质' WHERE id='model-std-department';
UPDATE models SET name='组织数字化模型',category='数字化基础',description='维护组织数字化属性、组织性质、组织层级和内设职级' WHERE id='model-std-org-rank';
UPDATE models SET name='阈值类属模型',category='数字化基础',description='维护金额、人员、天数与数字化标识的阈值类属' WHERE id='model-std-threshold-type';
UPDATE models SET name='模型时限模型',category='数字化基础',description='维护模型时限与适用业务领域' WHERE id='model-std-model-timeout';
UPDATE models SET name='模型数字化配置模型',category='数字化配置',description='维护模型数字化编码、数字化属性集合、数字化标识集合' WHERE id='model-config-digital';
UPDATE models SET name='标识关联配置模型',category='智选配置',description='维护数字化标识与关联数字化标识' WHERE id='model-config-identifier-trigger';
UPDATE models SET name='业务归属模型',category='数字化配置',description='维护组织名称与业务领域归属' WHERE id='model-config-business-ownership';

UPDATE digital_libraries SET name='员工信息数字化库',description='0622员工信息及历史兼容数据',updated_at=now() WHERE id='lib-standard-person';
UPDATE digital_libraries SET name='组织名称数字化库',description='0622组织名称数字化属性及历史兼容数据',updated_at=now() WHERE id='lib-standard-dept';
UPDATE digital_libraries SET name='组织数字化库',description='0622组织数字化属性及历史兼容数据',updated_at=now() WHERE id='lib-standard-org-rank';
UPDATE digital_libraries SET name='阈值类属数字化库',description='0622阈值类型与数字化标识类属',updated_at=now() WHERE id='lib-standard-threshold-type';
UPDATE digital_libraries SET name='模型时限数字化库',description='0622模型时限与适用业务领域',updated_at=now() WHERE id='lib-standard-model-timeout';
UPDATE digital_libraries SET name='模型数字化配置数字化库',description='0622模型数字化编码、业务属性、数字化标识集合',updated_at=now() WHERE id='lib-standard-digital-config';
UPDATE digital_libraries SET name='标识关联配置数字化库',description='数字化标识到关联数字化标识的正式配置；0622源文档未给出关联行',updated_at=now() WHERE id='lib-standard-identifier-trigger';
UPDATE digital_libraries SET name='业务归属数字化库',description='0622组织与业务领域归属',updated_at=now() WHERE id='lib-standard-business-ownership';
UPDATE digital_libraries SET name='审批分管配置数字化库',description='0622组织职级的行政审批/技术复核业务范围与阈值调整',updated_at=now() WHERE id='lib-standard-approval-assignment';

-- 3. 新增0622中独立存在且当前系统缺失的模型·库。
ON CONFLICT(name) DO UPDATE SET category=EXCLUDED.category,description=EXCLUDED.description;

SELECT v.lib_id,v.lib_name,m.id,'model',false,true,v.description,'active'
FROM (VALUES
 ('lib-digital-business-classification-0622','业务分类数字化库','业务分类模型','0622业务分类数字化属性数据'),
 ('lib-digital-org-relationship-0622','组织关系数字化库','组织关系模型','审批路径使用的组织隶属/分管关系'),
 ('lib-digital-employee-code-0622','员工数字化库','员工数字化模型','0622员工数字化编码案例')
) v(lib_id,lib_name,model_name,description)
JOIN models m ON m.name=v.model_name
ON CONFLICT(name) DO UPDATE SET model_id=EXCLUDED.model_id,allow_as_source=true,description=EXCLUDED.description,status='active',updated_at=now();

-- 4. 更新审批/智选当前正式模型数字化编码。0622未给这两个模型分配新的运行结果数字化标识，因此原结果标识仅保留历史兼容。
UPDATE model_projects p SET configuration=jsonb_set(jsonb_set(COALESCE(p.configuration,'{}'::jsonb),'{modelCode}',to_jsonb('5011001099001001001'::text),true),'{digitalStructureVersion}',to_jsonb('0622'::text),true),updated_at=now() FROM models m WHERE p.model_id=m.id AND m.name='审批模型';
UPDATE model_projects p SET configuration=jsonb_set(jsonb_set(COALESCE(p.configuration,'{}'::jsonb),'{modelCode}',to_jsonb('5011001099001001002'::text),true),'{digitalStructureVersion}',to_jsonb('0622'::text),true),updated_at=now() FROM models m WHERE p.model_id=m.id AND m.name='智选模型';

-- 用户确认：5011001006001001001 当前唯一对应会议收集模型；同步既有会议模型项目当前代码。
UPDATE model_projects p SET configuration=jsonb_set(COALESCE(p.configuration,'{}'::jsonb),'{modelCode}',to_jsonb(v.code::text),true),updated_at=now()
FROM models m JOIN (VALUES
 ('会议收集','5011001006001001001'),('会议组织','5011001006001001002'),('会议','5011001006001001003'),('会议纪要','5011001006001001004'),('参会反馈','5011001006001001010')
) v(name,code) ON m.name=v.name WHERE p.model_id=m.id;

SELECT 'dcode-v175-meeting-'||substr(md5(m.name),1,12),'model',m.id,v.code,m.name
FROM models m JOIN (VALUES
 ('会议收集','5011001006001001001'),('会议组织','5011001006001001002'),('会议','5011001006001001003'),('会议纪要','5011001006001001004'),('参会反馈','5011001006001001010')
) v(name,code) ON m.name=v.name
ON CONFLICT(object_type,object_id) DO UPDATE SET code=EXCLUDED.code,display_name=EXCLUDED.display_name,updated_at=now();

